#!/usr/bin/env node
/**
 * AUTO-GENERATED by GateMaster — trae 原生 hook
 * rule_key: mcp-stdio-kill-rec-9161
 * rule_statement: IF MCP服务器进程被杀 THEN MUST 连接器disable/enable重连
 * trae_event: PreToolUse
 * matcher: RunCommand
 *
 * 场景发散设计结论：
 *   触发场景：RunCommand 工具执行 kill/stop/taskkill/Stop-Process 等进程管理命令
 *   跳过场景：非进程管理命令、MCP 服务正常运行的常规操作
 *   边界情况：netstat 不可用/端口检查失败 → PASS（不阻断）
 *   检查逻辑：检测到 kill 类命令后，检查 memory-service 端口 3101 是否仍在监听
 *   失败建议：先重启 memory-service，再在客户端 disable→enable MCP 连接器
 */

import { execSync } from "child_process";
import { runHook } from "./_lib.mjs";

const KILL_PATTERNS = /\b(kill|taskkill|stop-process|Stop-Process|pkill|killall)\b/i;
const MCP_PORT = 3101;

function shouldRun(context) {
  const toolName = context.tool_name || context.llm_tool_name || "";
  if (!/RunCommand|Shell/i.test(toolName)) return false;
  const cmd = context.tool_input?.command || context.tool_input?.cmd || "";
  return KILL_PATTERNS.test(cmd);
}

function isPortListening(port) {
  try {
    const output = execSync(`netstat -ano | findstr :${port} | findstr LISTEN`, {
      encoding: "utf-8",
      timeout: 5000,
      stdio: ["pipe", "pipe", "pipe"]
    });
    return output.trim().length > 0;
  } catch {
    return false;
  }
}

function run(context) {
  const cmd = context.tool_input?.command || context.tool_input?.cmd || "";
  // 检查是否针对 MCP 相关进程
  const isMcpRelated = /mcp|memory-mcp|3101/i.test(cmd);
  if (!isMcpRelated) {
    // 非 MCP 相关的 kill，检查 MCP 端口是否受影响
    if (!isPortListening(MCP_PORT)) {
      return {
        action: "WARN",
        reason: `检测到进程被杀，且 memory-service 端口 ${MCP_PORT} 已不在监听。MCP 工具调用可能失败。`,
        suggestions: [
          "重启 memory-service: cd services/memory-service && npm start",
          "在客户端 MCP 连接器中先 disable 再 enable，触发重新连接",
          "确认 MCP 工具恢复正常后再继续操作"
        ]
      };
    }
  } else {
    // 直接杀 MCP 进程，必须提醒重连
    return {
      action: "REJECT",
      reason: `检测到直接杀掉 MCP/memory-service 进程。这会导致 MCP 工具调用失败。`,
      suggestions: [
        "如需重启 MCP 服务，请使用 graceful shutdown",
        "重启后必须在客户端 MCP 连接器中 disable→enable 触发重连",
        "确认 MCP 工具恢复正常后再继续操作"
      ]
    };
  }
  return { action: "PASS" };
}

runHook(shouldRun, run, "PreToolUse");
